import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import { evaluate, type Vector } from './evaluator.js';

// Captured from the passing dual-runtime suite at 823983722d before removing the
// TypeScript implementation. These are fixed expectations, never generated by Rust.
const vectors = readFileSync(new URL('./fixtures/vectors.jsonl', import.meta.url), 'utf8')
    .trimEnd()
    .split('\n')
    .map((line) => JSON.parse(line) as Vector);
const operations = [...new Set(vectors.map((v) => String(v.input.op)))].sort();
describe('native proxy preserved compatibility contracts', () => {
    test('retains the complete pre-removal baseline', () => {
        expect(vectors).toHaveLength(645);
        expect(operations).toHaveLength(24);
    });
    for (const operation of operations)
        test(operation, () => evaluate(vectors.filter((v) => v.input.op === operation)));
});
